var s=87;var a=`087-pressure-cooking`;var r=`070`;var i={en:`Pressure Cooking`,ua:`Приготування під тиском`};var n={short:`Pressure cooking raises the boiling temperature of water and can cook moist dishes faster. Pressure settings, fill limits, venting, and safe lid opening are central to the method.`,sections:[{title:`Core idea`,text:`A pressure cooker uses a locking lid, gasket, pressure regulation, and safety valves. Depending on its design, it may be an electric multicooker or a stovetop vessel. Pressure cooking is not the same as pressure canning: safe shelf-stable preservation requires approved canning equipment and tested schedules.`},{title:`Scientific / practical principles`,text:`At higher pressure, the boiling point of water increases, so wet cooking can take place above approximately 100°C at sea level. The exact temperature depends on the appliance and operating pressure; the contents still need time to heat through. Pressure affects boiling rather than replacing the physics of heat diffusion inside a thick piece.`},{title:`How to apply it`,text:`Inspect seals and vents, keep within the manufacturer’s minimum liquid and maximum fill limits, and lock the lid correctly. Choose a validated recipe, allow pressure to build, and begin timing when the specified pressure is reached. Release pressure using the method the recipe requires, keeping hands and face away from steam; open only after pressure has completely fallen.`},{title:`Practical example`,text:`Chickpeas or a beef stew may cook much faster in a pressure cooker than in an ordinary pot. Firm vegetables may need a shorter pressure phase or be added later, because fast tenderization can otherwise make them mushy.`},{title:`Common mistakes and limitations`,text:`Never force a pressurized lid, block a vent, or use untested amounts of thick foamy ingredients. The displayed countdown may exclude warm-up and depressurizing time. A pressure cooker is not automatically a safe pressure canner; consult tested home-canning guidance and equipment specifications for preservation.`},{title:`Safety boundary`,text:`Follow the specific cooker manual, especially for foaming foods such as legumes and grains. Pressure cookers are not automatically validated pressure canners for shelf-stable low-acid foods; canning requires separately tested equipment and processes. Never bypass the pressure-release mechanism.`},{title:`Related theories`,text:`047, 081, 085, 088.`}]};var o={short:`Приготування під тиском підвищує температуру кипіння води та пришвидшує приготування вологих страв. Важливі правильні режими тиску, межі заповнення, випуск пари й безпечне відкривання кришки.`,sections:[{title:`Суть`,text:`Скороварка має кришку з блокуванням, ущільнювач, регулятор тиску та захисні клапани. Вона може бути електричною або встановлюватися на плиту. Приготування під тиском і консервування під тиском є різними завданнями: для довготривалого зберігання потрібне дозволене обладнання й перевірені режими.`},{title:`Наукові та практичні принципи`,text:`За підвищеного тиску температура кипіння води зростає, тому вологе приготування можливе за температури понад приблизно 100 °C на рівні моря. Точне значення залежить від приладу та тиску. При цьому серцевина великого шматка все одно прогрівається поступово: тиск не скасовує теплопередачі всередині продукту.`},{title:`Як застосовувати`,text:`Перед роботою перевірте ущільнення й клапани, дотримуйтеся мінімальної кількості рідини та максимальної позначки наповнення. Беріть перевірений рецепт, запускайте відлік після досягнення потрібного тиску. Скидайте тиск зазначеним способом, відводячи руки й обличчя від пари; відкривайте лише після повного зниження тиску.`},{title:`Практичний приклад`,text:`Нут або рагу з яловичини можуть приготуватися в скороварці значно швидше, ніж у звичайній каструлі. Ніжні овочі часто потребують окремого короткого етапу, інакше вони розваряться.`},{title:`Поширені помилки й обмеження`,text:`Ніколи не намагайтеся силоміць відкрити посуд під тиском і не перекривайте клапани. Час, показаний на екрані, може не включати нагнітання й скидання тиску. Не використовуйте звичайну скороварку для домашнього консервування без підтвердженої придатності та перевіреної технології.`},{title:`Межа безпечності`,text:`Дотримуйтеся інструкції конкретної скороварки, особливо для бобових і круп, які можуть пінитися. Звичайна скороварка не є автоматично придатним автоклавом для консервування малокислотних продуктів на тривале зберігання; потрібне окремо перевірене обладнання й технологія. Ніколи не обходьте механізм скидання тиску.`},{title:`Пов’язані теорії`,text:`047, 081, 085, 088.`}]};var l=[47,81,85,88];var c=`References / Джерела`;var u=[`https://rouxbe.com/cooking-courses/culinary-foundations-rouxbe`,`https://nchfp.uga.edu/how/can/general-information/pressure-canners/`,`https://www.fda.gov/food/fda-food-code/food-code-2022`,`https://extension.oregonstate.edu/catalog/em-9152-safely-canning-foods-pressure-canners-pressure-cookers-electric-pressure-cookers`];var d={id:87,slug:a,group:`070`,title:i,en:n,ua:o,related:l,referenceTitle:c,references:u};export{d as default,n as en,r as group,s as id,c as referenceTitle,u as references,l as related,a as slug,i as title,o as ua};